def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_out(pos):
        r, c = pos
        return not (0 <= r < rows and 0 <= c < cols)

    if is_out(start) or is_out(goal):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    stack = [(start, [start])]
    visited = {start}

    while stack:
        current, path = stack.pop()
        if current == goal:
            return path
        row, col = current
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            new_pos = (new_row, new_col)
            if 0 <= new_row < rows and 0 <= new_col < cols:
                if grid[new_row][new_col] == '.' and new_pos not in visited:
                    visited.add(new_pos)
                    new_path = path + [new_pos]
                    stack.append((new_pos, new_path))

    return []

