        return []
    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []
    if start == goal:
        return [start]

    visited = set()

    def dfs(current):
        r, c = current
        if current in visited:
            return None
        visited.add(current)
        if current == goal:
            return [current]
