def solve(grid, start, goal):
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    if not is_valid(start) or not is_valid(goal):
        return []

    def is_wall(pos):
        r, c = pos
        return grid[r][c] == '#'

    if is_wall(start) or is_wall(goal):
        return []

    if start == goal:
        return [start]

    stack = [start]
    visited = {start}
    parent = {}
    found = False

    while stack:
        current = stack.pop()
        if current == goal:
            found = True
            break
        r, c = current
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            next_pos = (nr, nc)
            if is_valid(next_pos) and grid[nr][nc] == '.' and next_pos not in visited:
                visited.add(next_pos)
                parent[next_pos] = current
                stack.append(next_pos)

    if not found:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
    path.reverse()
    return path

